def dissemination(t):
    old = 'Точные адреса ресурсов предоставления доступа:'
    start=t.index(old);end=t.index('\n\n',start)
    t=t[:start]+'''Ресурсы предоставления доступа: https://sportsearch.shop/discover (поиск, в том числе режимы seeking и hot); https://sportsearch.shop/play/courts (каталог и карточки спортивных центров); https://sportsearch.shop/play/searches/invite/ с конкретным идентификатором приглашения. Связанные ответы API: https://sportsearch.shop/users/discover/guest, https://sportsearch.shop/users/discover, https://sportsearch.shop/courts и карточки по адресу https://sportsearch.shop/courts/ с конкретным идентификатором центра. Адрес конкретной карточки или приглашения сохраняется в экземпляре выбора пользователя. Приложение iOS: https://apps.apple.com/app/id6768862885; карта игроков входит в экран поиска и использует связанный API. Дополнительный ресурс не считается автоматически включённым в это согласие.'''+t[end:]
    t=t.replace('Зарегистрированные пользователи и гости без входа.', 'Зарегистрированные пользователи и гости без входа, включая посетителей на этапах заполнения черновика.')
    t=t.replace('- □ Публичная карточка выбранного игрового поиска.', '- □ Публичная карточка выбранного игрового поиска или приглашения.\n\n- □ Карточка игрока в каталоге спортивных центров и сведения о его связи с выбранным центром: [[ЦЕНТР_СВЯЗЬ_И_РАЗРЕШЁННЫЕ_ПОЛЯ]].')
    t=t.replace('Для каждого способа применяются выбранные поля', 'Прохождение этапов черновика не превращает гостевую аудиторию в определённый круг лиц и не разрешает публикацию самого черновика другого пользователя. Для каждого способа применяются выбранные поля')
    return t
